import { useCallback, useEffect, useRef, useState } from 'react';
import { VoiceSession, VoiceState } from './voice-session';

function newSessionId() {
  const rnd = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  return `vl-${rnd}`;
}

/**
 * useVoice — a self-contained live voice session for the launcher.
 * Returns { state, level, error, isActive, start, stop, toggle }.
 *
 * @param {object}   opts
 * @param {string}   opts.apiBaseUrl
 * @param {string}  [opts.userId]
 * @param {Function}[opts.getAuthHeaders]
 * @param {Function}[opts.fetchImpl]
 * @param {string}  [opts.lang]
 * @param {string}  [opts.sessionId]     reuse a specific session (else one is generated per session)
 * @param {Function}[opts.onTranscript]  (role, text, extra) => void
 * @param {Function}[opts.onError]       (Error) => void
 */
export function useVoice({ apiBaseUrl, userId, getAuthHeaders, fetchImpl, lang, voice, sessionId, onTranscript, onError } = {}) {
  const [state, setState] = useState(VoiceState.IDLE);
  const [error, setError] = useState(null);
  const [level, setLevel] = useState(0);
  const sessionRef = useRef(null);
  const rafRef = useRef(null);

  // Poll the live TTS amplitude while active, for the pulsing orb.
  useEffect(() => {
    const active = state !== VoiceState.IDLE && state !== VoiceState.ERROR;
    if (!active) { setLevel(0); return undefined; }
    let mounted = true;
    const tick = () => { if (!mounted) return; setLevel(sessionRef.current ? sessionRef.current.getLevel() : 0); rafRef.current = requestAnimationFrame(tick); };
    rafRef.current = requestAnimationFrame(tick);
    return () => { mounted = false; if (rafRef.current) cancelAnimationFrame(rafRef.current); };
  }, [state]);

  const stop = useCallback(async () => {
    const s = sessionRef.current;
    sessionRef.current = null;
    if (s) await s.stop();
    setState(VoiceState.IDLE);
  }, []);

  const start = useCallback(async () => {
    if (sessionRef.current) return;
    setError(null);
    const sess = new VoiceSession({
      sessionId: sessionId || newSessionId(),
      userId, lang, voice,
      config: { apiBaseUrl, userId, getAuthHeaders, fetchImpl },
      onState: setState,
      onTranscript: (role, text, extra) => { if (onTranscript) onTranscript(role, text, extra); },
      onError: (err) => { setError(err); setState(VoiceState.ERROR); if (onError) onError(err); sessionRef.current = null; },
    });
    sessionRef.current = sess;
    await sess.start();
  }, [apiBaseUrl, userId, getAuthHeaders, fetchImpl, lang, voice, sessionId, onTranscript, onError]);

  const toggle = useCallback(() => (sessionRef.current ? stop() : start()), [start, stop]);

  // V2: start a session (if needed) then ask the agent to explain a UI anchor.
  const explain = useCallback(async (anchor) => {
    if (!sessionRef.current) await start();
    // start() sets sessionRef before awaiting session.start(), which resolves once
    // the WS is open — so the session is connected here.
    if (sessionRef.current) sessionRef.current.sendExplain(anchor);
  }, [start]);

  useEffect(() => () => { if (sessionRef.current) sessionRef.current.stop(); }, []);

  const isActive = state !== VoiceState.IDLE && state !== VoiceState.ERROR;
  return { state, level, error, isActive, start, stop, toggle, explain };
}

export { VoiceState };
