/**
 * Per-instance config helpers for the voice launcher. Unlike the chat package
 * (module-global config), the launcher takes its config as props and threads a
 * plain config object through the session — so multiple launchers / hosts never
 * clobber each other.
 *
 * config = { apiBaseUrl, userId?, getAuthHeaders?, fetchImpl?, eventSourceImpl? }
 * apiBaseUrl must already end at the API root (e.g. ".../api/v1").
 */

export function apiUrl(config, path) {
  const base = (config.apiBaseUrl || '').replace(/\/+$/, '');
  if (!base) throw new Error('[voice-launcher] apiBaseUrl is not configured. Pass it to <VoiceLauncher apiBaseUrl="…/api/v1" />.');
  return `${base}${path}`;
}

export function getFetch(config) {
  return config.fetchImpl || globalThis.fetch.bind(globalThis);
}

export async function buildHeaders(config, extra = {}) {
  const auth = typeof config.getAuthHeaders === 'function' ? await config.getAuthHeaders() : null;
  return { ...extra, ...(auth || {}) };
}
