import React from 'react';

/**
 * VoiceResponsePanel (CS-4) — a compact panel that surfaces the LAST spoken
 * assistant response (and its choice controls) to the LEFT of the voice FAB, for
 * when voice is active but the text window is closed. The user can read what was
 * said and click an option instead of speaking it. Bottom-anchored; it grows
 * UPWARD with content (column-reverse) and scrolls once it hits the viewport top.
 *
 * Controls are rendered as simple chips (option b, PO/architect): each dispatches
 * a `controlAction` over the SHARED session via the host — no cross-package
 * ControlRenderer dependency.
 */
export default function VoiceResponsePanel({ response, onControlClick, onClose, labels = {} }) {
  if (!response || !response.text) return null;
  const controls = Array.isArray(response.controls) ? response.controls : [];
  // Flatten choice/confirm controls → option chips.
  const chips = controls.flatMap((c) => (Array.isArray(c.options) ? c.options : []).map((o) => ({
    key: `${c.id || c.slotId}:${o.value}`,
    label: o.label || String(o.value),
    action: { slotId: c.slotId, action: c.type === 'confirm' ? 'confirm' : 'select', value: o.value },
  })));

  return (
    <div className="fdvl-response-panel" role="status" aria-live="polite">
      <button
        type="button"
        className="fdvl-response-close"
        onClick={onClose}
        aria-label={labels.close || 'Close'}
        title={labels.close || 'Close'}
      >
        ×
      </button>
      <div className="fdvl-response-text">{response.text}</div>
      {chips.length > 0 && (
        <div className="fdvl-response-chips">
          {chips.map((chip) => (
            <button
              key={chip.key}
              type="button"
              className="fdvl-response-chip"
              onClick={() => onControlClick && onControlClick(chip.action, chip.label)}
            >
              {chip.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
